import { expect, test } from "bun:test";

import { normalizeModelName, rankCandidates, resolveModelId } from "../src/identity.ts";

test("reported wins when it is the only signal", () => {
  expect(resolveModelId({ reported_by_provider: "provider-model-x" })).toBe("provider-model-x");
});

test("served is used without a report", () => {
  expect(resolveModelId({ served_alias: "served-y" })).toBe("served-y");
});

test("requested is the last fallback", () => {
  expect(resolveModelId({ requested: "asked-z" })).toBe("asked-z");
});

test("nothing left is unknown", () => {
  expect(resolveModelId({})).toBe("unknown");
});

test("normalize lowercases and dashes", () => {
  expect(normalizeModelName("Qwen_3.6 27B Q8")).toBe("qwen-3.6-27b-q8");
});

test("rank dedupes and sorts", () => {
  expect(rankCandidates([{ requested: "b" }, { requested: "a" }, { requested: "b" }])).toEqual([
    "a",
    "b",
  ]);
});
